// Confere o token enviado pelo site e monta o texto do aviso.
const TOKEN = 'COLE_AQUI_O_MESMO_VALOR_DE_N8N_WEBHOOK_TOKEN_ATENDIMENTO';
const item = $input.first().json;
const recebido = (item.headers || {})['x-webhook-token'] || '';
if (recebido !== TOKEN) { throw new Error('Token inválido: o aviso foi recusado'); }

const d = item.body || {};
const limpa = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);
let numero = String(d.whatsapp || '').replace(/\D/g, '');
if (numero.length === 10 || numero.length === 11) numero = '55' + numero;
const link = numero ? 'https://wa.me/' + numero : '(sem WhatsApp)';

let mensagem;
let assunto;
if (d.evento === 'contato_novo') {
  assunto = 'Novo contato nº ' + d.numero + ' - ' + limpa(d.assunto, 60);
  mensagem = [
    '💬 Novo CONTATO no site nº ' + d.numero,
    'Nome: ' + limpa(d.nome, 120),
    'WhatsApp: ' + (limpa(d.whatsapp, 30) || '(não informou)'),
    'E-mail: ' + (limpa(d.email, 160) || '(não informou)'),
    'Assunto: ' + limpa(d.assunto, 80),
    'Página: ' + (limpa(d.pagina, 80) || '(contato)'),
    'Mensagem: ' + limpa(d.mensagem, 1500),
    'Responder: ' + link,
  ].join('\n');
} else if (d.evento === 'operador_candidato') {
  assunto = 'Novo candidato a operador: ' + limpa(d.nome, 60);
  mensagem = [
    '🧑‍🔧 Novo CANDIDATO a operador',
    'Nome: ' + limpa(d.nome, 120),
    'WhatsApp: ' + limpa(d.whatsapp, 30),
    'Cidade: ' + (limpa(d.cidade, 80) || '(não informou)'),
    'Interesse: ' + (limpa(d.interesse, 300) || '(não informou)'),
    'Origem: ' + (limpa(d.origem, 60) || '(direto)'),
    'Responder: ' + link,
  ].join('\n');
} else {
  throw new Error('Evento desconhecido');
}

return [{ json: { mensagem, assunto, evento: d.evento, link } }];
